int[] ints = new int[] {1,4,6,8,9,11,15};
int s = 10;
int L = -1;
int R = ints.length;
int M = (L + R) / 2;
while(R - L > 1)
{
  /*LINE:*/
  M = (L + R) / 2;
  int c = ints[M];
  if(c <= s)
    L = M;
  else
    R = M;
}
out.print(L);

