public static int dp(int[] ints)
{
  int[] dp = new int[ints.length];
  Arrays.fill(dp, 1);
  int ret = 0;
  for(int i = 1;i<dp.length;i++)
  {
    for(int j = i-1;j>=0;j--)
    {
      if(ints[j] <= ints[i])
      {
        dp[i] = Math.max(dp[i],dp[j] + 1);
      }
    }
    ret = Math.max(ret, dp[i]);
  }
  return ret;
}

public static int rec(int[] ints, int ind)
{
  int r = 1;
  for(int i = ind+1;i<ints.length;i++)
  {
    if(ints[i] >= ints[ind])
    r = Math.max(r, 1 + rec(ints, i));
  }
  return r;
}

