public class pet{


  private int weight;
  private String name;


  public pet(int w, String n)
  {
    this.weight = w;
    this.name = n;
  }


  public boolean equals(pet p)
  {
    if(weight == p.weight){
      return name.equals(p.name);
    }
    return false;
  }


  public String toString()
  {
    return name+" "+weight;
  }


}

private class fish extends pet{


  public fish(int w, String n)
  {
    super(w, n);
  }


  public boolean equals(pet p)
  {
    if(p instanceof fish)
      return p.equals(this);
    return false;
  }


}

