public class Structure{ 



  int[] p; 
  public Structure(int sz) 
  { 
     p = new int[sz]; 
     Arrays.fill(p, -1); 
  } 


  public int find(int x) 
  { 
     if(p[x] < 0) 
        return x; 
     int ret = find(p[x]); 
     p[x] = ret; 
     return ret; 
  } 


  public int sz(int x) 
  { 
     return -p[find(x)]; 
  } 


  public boolean union(int a, int b) 
  { 
     int pa = find(a); 
     int pb = find(b); 
     if(pa == pb) { 
        return false; 
     } 
     p[pa] += p[pb]; 
     p[pb] = pa; 
     return true; 
  } 

} 
